#!/usr/bin/env python3
from pathlib import Path
import sys

root = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path('build/PrePoMax-CodeAster').resolve()

# Expose a read-only qualification seam on vtkControl. The first C8.74 attempt compared
# aggregate VTK actor bounds to full FE-mesh bounds; that is too strict because rendered
# result actors are a surface subset of the volume mesh. Instead, qualify the actual VTK
# point coordinates against the already-deformed live FeResults mesh.
vtk = root / 'vtkControl' / 'vtkControl.cs'
text = vtk.read_text(encoding='utf-8-sig')
anchor = '''        // Callbacks                                                                                                                \n'''
helper = '''        // AsterMax C8.74 qualification seam: verify that every point handed to visible\n        // ColorContours VTK actors exists in the expected deformed Results mesh. The seam\n        // is read-only and inspects the mapper input actually used by rendering.\n        public double AsterMaxGetVisibleContourPointMatchErrorForQualification(double[][] expectedNodeCoordinates,\n                                                                                double[][] requiredCoordinates,\n                                                                                out int actorCount,\n                                                                                out long renderedPointCount,\n                                                                                out double requiredPointMaxError)\n        {\n            if (expectedNodeCoordinates == null || expectedNodeCoordinates.Length == 0)\n                throw new ArgumentException("Expected deformed mesh coordinates are empty.");\n\n            actorCount = 0;\n            renderedPointCount = 0;\n            requiredPointMaxError = 0;\n            double maxNearestError = 0;\n            List<double[]> renderedPoints = new List<double[]>();\n\n            foreach (vtkMaxActor actor in _actors.Values)\n            {\n                if (actor == null || !actor.ColorContours || actor.Geometry == null) continue;\n                if (actor.Geometry.GetVisibility() != 1 || actor.Geometry.GetMapper() == null) continue;\n                vtkDataSet input = actor.Geometry.GetMapper().GetInput();\n                if (input == null) continue;\n                long n = input.GetNumberOfPoints();\n                if (n <= 0) continue;\n                actorCount++;\n                for (long i = 0; i < n; i++)\n                {\n                    double[] p = input.GetPoint(i);\n                    if (p == null || p.Length < 3) continue;\n                    renderedPoints.Add(new double[] { p[0], p[1], p[2] });\n                    renderedPointCount++;\n\n                    double nearest2 = Double.PositiveInfinity;\n                    for (int j = 0; j < expectedNodeCoordinates.Length; j++)\n                    {\n                        double[] q = expectedNodeCoordinates[j];\n                        double dx = p[0] - q[0];\n                        double dy = p[1] - q[1];\n                        double dz = p[2] - q[2];\n                        double d2 = dx * dx + dy * dy + dz * dz;\n                        if (d2 < nearest2) nearest2 = d2;\n                    }\n                    maxNearestError = Math.Max(maxNearestError, Math.Sqrt(nearest2));\n                }\n            }\n\n            if (actorCount == 0 || renderedPointCount == 0)\n                throw new InvalidOperationException("No visible VTK ColorContours geometry points found for C8.74 qualification.");\n\n            if (requiredCoordinates != null)\n            {\n                foreach (double[] q in requiredCoordinates)\n                {\n                    double nearest2 = Double.PositiveInfinity;\n                    foreach (double[] p in renderedPoints)\n                    {\n                        double dx = p[0] - q[0];\n                        double dy = p[1] - q[1];\n                        double dz = p[2] - q[2];\n                        double d2 = dx * dx + dy * dy + dz * dz;\n                        if (d2 < nearest2) nearest2 = d2;\n                    }\n                    requiredPointMaxError = Math.Max(requiredPointMaxError, Math.Sqrt(nearest2));\n                }\n            }\n\n            return maxNearestError;\n        }\n\n'''
if helper not in text:
    if anchor not in text:
        raise SystemExit('vtkControl callbacks anchor not found; refusing partial C8.74 patch.')
    text = text.replace(anchor, helper + anchor, 1)
vtk.write_text(text, encoding='utf-8')

frm = root / 'PrePoMax' / 'Forms' / 'FrmMain.cs'
f = frm.read_text(encoding='utf-8-sig')
frm_anchor = '''        public string GetDeformationVariable()\n        {\n'''
frm_helper = '''        // AsterMax C8.74: read-only inspection of the live rendered contour mapper points.\n        public double AsterMaxGetRenderedContourPointMatchErrorForQualification(double[][] expectedNodeCoordinates,\n                                                                                 double[][] requiredCoordinates,\n                                                                                 out int actorCount,\n                                                                                 out long renderedPointCount,\n                                                                                 out double requiredPointMaxError)\n        {\n            if (_vtk == null) throw new InvalidOperationException("VTK control is not initialized.");\n            return _vtk.AsterMaxGetVisibleContourPointMatchErrorForQualification(expectedNodeCoordinates, requiredCoordinates,\n                                                                                  out actorCount, out renderedPointCount,\n                                                                                  out requiredPointMaxError);\n        }\n\n'''
if frm_helper not in f:
    if frm_anchor not in f:
        raise SystemExit('FrmMain deformation getter anchor not found; refusing partial C8.74 patch.')
    f = f.replace(frm_anchor, frm_helper + frm_anchor, 1)
frm.write_text(f, encoding='utf-8')

demo = root / 'PrePoMax' / 'CodeAster' / 'CodeAsterResultsDemo.cs'
d = demo.read_text(encoding='utf-8')
old = '''                NativeScalarBarGate.Report scalarBarReport = NativeScalarBarGate.Verify(controller, min, max);\n'''
new = '''                // C8.74 corrected gate: rendered result actors are a surface subset of the\n                // volume mesh, so full-mesh aggregate bounds are not a valid equality contract.\n                // Instead every VTK mapper point must coincide with a node in the verified x10\n                // FeResults mesh, and solver-provenance extrema nodes N21/N22 must both be present.\n                double[][] deformedNodeCoordinates = new double[results.Mesh.Nodes.Count][];\n                int coordinateIndex = 0;\n                foreach (FeNode meshNode in results.Mesh.Nodes.Values)\n                    deformedNodeCoordinates[coordinateIndex++] = new double[] { meshNode.Coor[0], meshNode.Coor[1], meshNode.Coor[2] };\n\n                double[][] requiredRenderedCoordinates = new double[renderControlNodes.Length][];\n                for (int ri = 0; ri < renderControlNodes.Length; ri++)\n                {\n                    FeNode requiredNode = results.Mesh.Nodes[renderControlNodes[ri]];\n                    requiredRenderedCoordinates[ri] = new double[] { requiredNode.Coor[0], requiredNode.Coor[1], requiredNode.Coor[2] };\n                }\n\n                int renderedContourActorCount;\n                long renderedContourPointCount;\n                double renderedRequiredPointMaxError;\n                double renderedPointMeshMaxError = controller.Form.AsterMaxGetRenderedContourPointMatchErrorForQualification(\n                    deformedNodeCoordinates, requiredRenderedCoordinates, out renderedContourActorCount,\n                    out renderedContourPointCount, out renderedRequiredPointMaxError);\n                const double renderedPointTolerance = 1e-6;\n                if (renderedContourActorCount < 1 || renderedContourPointCount < 1)\n                    throw new InvalidDataException("C8.74 no rendered contour geometry found.");\n                if (renderedPointMeshMaxError > renderedPointTolerance)\n                    throw new InvalidDataException("C8.74 VTK mapper contains points not matching the x10 Results mesh. max_error=" + renderedPointMeshMaxError);\n                if (renderedRequiredPointMaxError > renderedPointTolerance)\n                    throw new InvalidDataException("C8.74 solver-provenance extrema nodes are not both represented in the rendered contour geometry. max_error=" + renderedRequiredPointMaxError);\n\n                NativeScalarBarGate.Report scalarBarReport = NativeScalarBarGate.Verify(controller, min, max);\n'''
if old not in d:
    raise SystemExit('NativeScalarBarGate anchor not found; refusing partial C8.74 patch.')
d = d.replace(old, new, 1)

payload_old = '''                    "  \\\"deformation_ui_scale_selector_verified\\\": true,\\n" +\n                    "  \\\"render_mesh_deformation_source\\\": \\\"FeResults.SetMeshDeformation(scale,step,increment)\\\",\\n" +'''
payload_new = '''                    "  \\\"deformation_ui_scale_selector_verified\\\": true,\\n" +\n                    "  \\\"rendered_viewport_deformation_source\\\": \\\"vtkControl visible ColorContours mapper input points -> x10 FeResults mesh\\\",\\n" +\n                    "  \\\"rendered_viewport_contour_actor_count\\\": " + renderedContourActorCount.ToString(CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_contour_point_count\\\": " + renderedContourPointCount.ToString(CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_point_mesh_max_error_mm\\\": " + renderedPointMeshMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_required_extrema_max_error_mm\\\": " + renderedRequiredPointMaxError.ToString("R", CultureInfo.InvariantCulture) + ",\\n" +\n                    "  \\\"rendered_viewport_deformation_verified\\\": true,\\n" +\n                    "  \\\"render_mesh_deformation_source\\\": \\\"FeResults.SetMeshDeformation(scale,step,increment)\\\",\\n" +'''
if payload_old not in d:
    raise SystemExit('C8.73 READY payload anchor not found; refusing partial C8.74 patch.')
d = d.replace(payload_old, payload_new, 1)

old_provenance = '''            provenance.Text = "SOLVER VERIFIED  |  native deformation UI x10 verified  |  mm-N-MPa";\n'''
new_provenance = '''            provenance.Text = "SOLVER VERIFIED  |  rendered deformation x10 verified  |  mm-N-MPa";\n'''
if old_provenance not in d:
    raise SystemExit('C8.73 provenance anchor not found; refusing partial C8.74 patch.')
d = d.replace(old_provenance, new_provenance, 1)

demo.write_text(d, encoding='utf-8')
print(f'Patched {vtk} with rendered mapper-point correspondence qualification')
print(f'Patched {frm} with live VTK point qualification bridge')
print(f'Patched {demo} with corrected C8.74 viewport deformation gate')
